import { BuscadorPizzas } from "./BuscadorPizzas.jsx";

const PIZZAS = [
  "Americana",
  "Hawaiana",
  "Pepperoni",
  "Margarita",
  "Vegetariana",
  "Lomo saltado",
  "Ají de gallina",
  "Chorizo y pimiento",
  "Cuatro quesos",
];

// Simula una petición al servidor: tarda 600 ms y falla si buscas "error".
function buscar(consulta) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const texto = consulta.toLowerCase();
      if (texto === "error") reject(new Error("Sin conexión"));
      else resolve(PIZZAS.filter((pizza) => pizza.toLowerCase().includes(texto)));
    }, 600);
  });
}

export default function App() {
  return (
    <main style={{ maxWidth: 420, margin: "2rem auto", fontFamily: "system-ui, sans-serif" }}>
      <h1>Carta de pizzas</h1>
      <BuscadorPizzas buscar={buscar} />
    </main>
  );
}
